class Complex {
public:
    int re, im;
    Complex(int r = 0, int i = 0) : re(r), im(i) {}
    Complex& operator+=(const Complex& other) {
        re += other.re;
        im += other.im;
        return *this;
    }
    bool operator==(const Complex& other) const {
        return re == other.re && im == other.im;
    }
    void show() const {
        if (im < 0)
            cout << re << " - " << (-im) << "i";
        else
            cout << re << " + " << im << "i";
    }
};

int main() {
    int r1, i1, n, r2, i2;
    cin >> r1 >> i1 >> n;
    Complex sum(r1, i1);
    for (int k = 0; k < n; k++) {
        int r, i;
        cin >> r >> i;
        sum += Complex(r, i);
    }
    cin >> r2 >> i2;
    Complex expected(r2, i2);
    cout << "Sum: ";
    sum.show();
    cout << endl;
    if (sum == expected)
        cout << "Equal" << endl;
    else
        cout << "Not equal" << endl;
    return 0;
}

