    Time(int hh = 0, int mm = 0) : h(hh), m(mm) {}
    Time& operator++() {
        m++;
        if (m == 60) {
            m = 0;
            h = (h + 1) % 24;
        }
        return *this;
    }
    void show() const {
        cout << setw(2) << setfill('0') << h << ":"
             << setw(2) << m << endl;
    }
};

