    int h, m, n;
    cin >> h >> m >> n;
    Time t(h, m);
    cout << "Before: ";
    t.show();
    for (int k = 0; k < n; k++) {
        ++t;
    }
    cout << "After: ";
    t.show();
    return 0;
}

